      "options": [
        "Nucleophilic addition",
        "Only free radical substitution",
        "No reactions",
        "Only elimination always"
      ],
      "correct_answer": "Nucleophilic addition",
      "explanation": "Polarized carbonyl carbon attacked by nucleophile."
    },
